use magnus::{exception, function, prelude::*, Error, ExceptionClass, RModule, RString, Ruby};
use std::sync::Once;

/// Raw FFI bindings generated by bindgen from the xmlsec1/libxml2 headers.
/// Nothing in here is safe to call directly outside this crate — every
/// call site must uphold libxmlsec1's own invariants (init-before-use,
/// non-null docs/nodes, matching create/destroy pairs, etc). The `validate`
/// functions below are the only places that do so.
#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::upper_case_acronyms
)]
mod sys {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

static INIT: Once = Once::new();

/// Initializes xmlsec + its OpenSSL crypto backend exactly once per process,
/// the first time it's actually needed. Ruby callers never have to think
/// about init/shutdown ordering.
fn ensure_initialized() -> Result<(), &'static str> {
    let mut result = Ok(());
    INIT.call_once(|| unsafe {
        if sys::xmlSecInit() < 0 {
            result = Err("xmlSecInit failed");
        } else if sys::xmlSecOpenSSLAppInit(std::ptr::null()) < 0 {
            result = Err("xmlSecOpenSSLAppInit failed");
        } else if sys::xmlSecOpenSSLInit() < 0 {
            result = Err("xmlSecOpenSSLInit failed");
        }
    });
    result
}

fn xmlsec_error_class(ruby: &Ruby) -> ExceptionClass {
    ruby.eval::<ExceptionClass>("XmlsecRb::Error")
        .unwrap_or_else(|_| exception::runtime_error())
}

fn xmlsec_error(ruby: &Ruby, message: impl Into<String>) -> Error {
    Error::new(xmlsec_error_class(ruby), message.into())
}

/// A tiny RAII guard so every early-return in `verify_signature` still frees
/// the xmlsec keys manager and dsig context it allocated. Deliberately does
/// *not* own the libxml2 doc — see `validate_bytes` vs `validate_doc_pointer`
/// below for why doc ownership has to be handled by the caller instead.
struct DsigResources {
    mngr: sys::xmlSecKeysMngrPtr,
    dsig_ctx: sys::xmlSecDSigCtxPtr,
}

impl Drop for DsigResources {
    fn drop(&mut self) {
        unsafe {
            if !self.dsig_ctx.is_null() {
                sys::xmlSecDSigCtxDestroy(self.dsig_ctx);
            }
            if !self.mngr.is_null() {
                sys::xmlSecKeysMngrDestroy(self.mngr);
            }
        }
    }
}

/// Verifies the XML-DSig `<Signature>` found under `doc`'s root element
/// against the trusted certificate `cert_pem` (PEM-encoded). Doesn't take
/// ownership of `doc` — the caller decides whether/when to free it, since
/// that differs between a doc we parsed ourselves and one borrowed from a
/// Nokogiri document that Ruby's GC still owns.
///
/// Mirrors xmlsec's own `verify2` example: find the `<Signature>` node,
/// build a keys manager trusting only `cert_pem`, create a dsig context,
/// verify, check `status`.
unsafe fn verify_signature(
    ruby: &Ruby,
    doc: sys::xmlDocPtr,
    cert_pem: &[u8],
) -> Result<bool, Error> {
    let root = sys::xmlDocGetRootElement(doc);
    if root.is_null() {
        return Err(xmlsec_error(ruby, "XML document has no root element"));
    }

    let sig_node = sys::xmlSecFindNode(
        root,
        sys::xmlSecNodeSignature.as_ptr(),
        sys::xmlSecDSigNs.as_ptr(),
    );
    if sig_node.is_null() {
        return Err(xmlsec_error(ruby, "no <Signature> element found in document"));
    }

    let mut resources = DsigResources {
        mngr: std::ptr::null_mut(),
        dsig_ctx: std::ptr::null_mut(),
    };

    resources.mngr = sys::xmlSecKeysMngrCreate();
    if resources.mngr.is_null() {
        return Err(xmlsec_error(ruby, "failed to create xmlsec keys manager"));
    }
    if sys::xmlSecOpenSSLAppDefaultKeysMngrInit(resources.mngr) < 0 {
        return Err(xmlsec_error(ruby, "failed to initialize xmlsec keys manager"));
    }
    if sys::xmlSecOpenSSLAppKeysMngrCertLoadMemory(
        resources.mngr,
        cert_pem.as_ptr(),
        cert_pem.len(),
        sys::xmlSecKeyDataFormat_xmlSecKeyDataFormatPem,
        sys::xmlSecKeyDataTypeTrusted,
    ) < 0
    {
        return Err(xmlsec_error(ruby, "failed to load trusted certificate"));
    }

    resources.dsig_ctx = sys::xmlSecDSigCtxCreate(resources.mngr);
    if resources.dsig_ctx.is_null() {
        return Err(xmlsec_error(ruby, "failed to create xmlsec signature context"));
    }

    // A negative return here isn't always a processing *error* in the sense
    // this function should raise for: xmlsec returns < 0 (rather than
    // setting status to Invalid) for "no key satisfies this KeyInfo",
    // which is exactly what happens when the signature's embedded
    // certificate doesn't match the trusted `cert_pem` we gave it — the
    // ordinary "wrong certificate" outcome, not a malformed-input error.
    // Every other precondition that would make verification meaningless
    // (bad XML, no <Signature>, cert failed to load at all) was already
    // raised above, before we ever got here.
    if sys::xmlSecDSigCtxVerify(resources.dsig_ctx, sig_node) < 0 {
        return Ok(false);
    }

    let status = (*resources.dsig_ctx).status;
    Ok(status == sys::xmlSecDSigStatus_xmlSecDSigStatusSucceeded)
}

/// Entry point for `XmlsecRb.validate` given an XML String or the contents
/// read from a path. We own the parse, so we own the free.
fn validate_bytes(ruby: &Ruby, xml: RString, cert_pem: RString) -> Result<bool, Error> {
    ensure_initialized().map_err(|message| xmlsec_error(ruby, message))?;

    let xml_bytes = unsafe { xml.as_slice() };
    let cert_bytes = unsafe { cert_pem.as_slice() };

    unsafe {
        let doc = sys::xmlReadMemory(
            xml_bytes.as_ptr().cast(),
            xml_bytes.len() as i32,
            std::ptr::null(),
            std::ptr::null(),
            0,
        );
        if doc.is_null() {
            return Err(xmlsec_error(ruby, "failed to parse XML document"));
        }
        let result = verify_signature(ruby, doc, cert_bytes);
        sys::xmlFreeDoc(doc);
        result
    }
}

/// Entry point for `XmlsecRb.validate` given a `Nokogiri::XML::Document`.
/// `doc_pointer` is that document's `#pointer_id` — the address of the
/// libxml2 `xmlDoc` Nokogiri already parsed and holds via Ruby's GC. We
/// never parse or free it ourselves: freeing a doc Ruby still thinks it
/// owns would be a use-after-free the moment the GC gets to it. This also
/// avoids a to_xml-and-reparse round trip for documents the caller just
/// built in memory (e.g. about to be signed).
fn validate_doc_pointer(ruby: &Ruby, doc_pointer: usize, cert_pem: RString) -> Result<bool, Error> {
    ensure_initialized().map_err(|message| xmlsec_error(ruby, message))?;

    if doc_pointer == 0 {
        return Err(xmlsec_error(ruby, "invalid (null) document pointer"));
    }
    let doc = doc_pointer as sys::xmlDocPtr;
    let cert_bytes = unsafe { cert_pem.as_slice() };

    unsafe { verify_signature(ruby, doc, cert_bytes) }
}

/// True when the linked libxmlsec1 matches the version these bindings were
/// generated against. A real call into libxmlsec1 (xmlSecCheckVersionExt),
/// not a compile-time constant.
fn check_version() -> bool {
    unsafe {
        sys::xmlSecCheckVersionExt(
            sys::XMLSEC_VERSION_MAJOR as i32,
            sys::XMLSEC_VERSION_MINOR as i32,
            sys::XMLSEC_VERSION_SUBMINOR as i32,
            sys::xmlSecCheckVersionMode_xmlSecCheckVersionExactMatch,
        ) == 1
    }
}

#[magnus::init]
fn init(ruby: &Ruby) -> Result<(), Error> {
    let module = ruby.define_module("XmlsecRb")?;
    let native: RModule = module.define_module("Native")?;
    native.define_singleton_method("check_version", function!(check_version, 0))?;
    native.define_singleton_method("validate_bytes", function!(validate_bytes, 2))?;
    native.define_singleton_method("validate_doc_pointer", function!(validate_doc_pointer, 2))?;
    Ok(())
}
